import {CHAPTERS,META} from './content.js';
import {createWorld} from './scene.js';
import {CHILD_GUIDES} from './child-content.js';
import {localDay,normalizeReviews,recordReview,getReviewQueue,mergeReviews} from './review-engine.js';
import {createNarrator} from './narrator.js';
import {listChineseVoices} from './voice-options.js';
import {KNOWLEDGE_TOPICS,normalizeKnowledgeProgress,mergeKnowledgeProgress} from './knowledge-model.js';
import {createKnowledgeUI} from './knowledge-ui.js';
import {renderActivitySheet} from './activity-sheet.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORAGE='yunshan-academy-v1';
const names=['启蒙','礼仪','博物','典籍','历史','勤学'];
const places=['明心岛','知礼桥','万象园','藏经阁','岁月台','勤学亭'];
const descriptions=['从认识自己，到认识世界。','在关爱与尊重里，学会相处。','一草一木，一方辽阔天地。','翻开典籍，与先贤隔空对话。','沿着时间的长河，观兴衰变迁。','让每一次坚持，都留下光。'];
const stepNames=['读一读','补一句','拼一拼','想一想','已完成'];
const validIndex=i=>Number.isInteger(i)&&i>=0&&i<CHAPTERS.length;
const unique=a=>[...new Set(a)];
const chunks=v=>v.text.split(/[，。！？；,.;!?]/).map(s=>s.trim()).filter(Boolean);
const allPhrases=unique(CHAPTERS.flatMap(c=>c.verses.flatMap(chunks)));
const normalizeSearch=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[\s，。！？；、,.!?;:“”‘’"'（）()·-]/g,'');
const defaultData=()=>({version:1,completed:[],bookmarks:[],mistakes:[],last:0,visits:[],drafts:{},reviews:{},knowledge:{},knowledgeCursor:{topic:'astronomy',item:'sun',year:1120},settings:{voiceURI:'',challenge:'gentle',large:true,pinyin:true,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,rate:.85,day:false}});
const emptyDraft=id=>({stage:0,readDone:false,readIndex:0,readSeen:[],recallHelp:{},orderHelp:false,quizHelp:false,recallAnswers:CHAPTERS[id].verses.map(()=>false),recallIndex:0,recallChoices:{},recallWrong:{},order:[],orderChoices:[],orderSolved:false,quizSolved:false,quizWrong:[],scroll:0,updatedAt:0});
function validBookmark(k){if(typeof k!=='string'||!/^\d+:\d+$/.test(k))return false;const[c,v]=k.split(':').map(Number);return Boolean(CHAPTERS[c]?.verses[v])}
function maxStage(d,id,completed=[]){if(completed.includes(id))return 4;if(!d.readDone)return 0;if(!d.recallAnswers.every(Boolean))return 1;if(!d.orderSolved)return 2;return 3}
function normalizeDraft(raw,id,completed=[]){
 const d=emptyDraft(id),r=raw&&typeof raw==='object'?raw:{};d.readDone=r.readDone===true;
 d.readIndex=Number.isInteger(r.readIndex)?Math.max(0,Math.min(r.readIndex,CHAPTERS[id].verses.length-1)):0;d.readSeen=Array.isArray(r.readSeen)?unique(r.readSeen.filter(i=>Number.isInteger(i)&&i>=0&&i<CHAPTERS[id].verses.length)):[];d.orderHelp=r.orderHelp===true;d.quizHelp=r.quizHelp===true;for(let i=0;i<CHAPTERS[id].verses.length;i++)if(r.recallHelp?.[i]===true)d.recallHelp[i]=true;
 d.recallAnswers=d.recallAnswers.map((_,i)=>r.recallAnswers?.[i]===true);
 d.recallIndex=Number.isInteger(r.recallIndex)?Math.min(Math.max(r.recallIndex,0),d.recallAnswers.length-1):0;
 d.order=Array.isArray(r.order)?unique(r.order.filter(i=>Number.isInteger(i)&&i>=0&&i<4)):[];
 d.orderChoices=Array.isArray(r.orderChoices)&&r.orderChoices.length===4&&unique(r.orderChoices).length===4&&r.orderChoices.every(i=>Number.isInteger(i)&&i>=0&&i<4)?r.orderChoices:[];
 const orderText=chunks(CHAPTERS[id].verses[id%CHAPTERS[id].verses.length]);
 d.orderSolved=r.orderSolved===true&&d.order.length===4&&d.order.every((v,i)=>orderText[v]===orderText[i]);d.quizSolved=r.quizSolved===true&&d.orderSolved;
 d.quizWrong=Array.isArray(r.quizWrong)?unique(r.quizWrong.filter(i=>Number.isInteger(i)&&i>=0&&i<4&&i!==CHAPTERS[id].quiz.answer)):[];
 for(let i=0;i<d.recallAnswers.length;i++){
  const p=r.recallChoices?.[i],answer=chunks(CHAPTERS[id].verses[i])[(i+1)%4];
  if(Array.isArray(p)&&[2,4].includes(p.length)&&unique(p).length===p.length&&p.includes(answer)&&p.every(s=>typeof s==='string'&&allPhrases.includes(s)))d.recallChoices[i]=p;
  const wrong=r.recallWrong?.[i];d.recallWrong[i]=Array.isArray(wrong)?unique(wrong.filter(s=>typeof s==='string'&&s!==answer&&allPhrases.includes(s))):[];
 }
 d.stage=Number.isInteger(r.stage)?Math.min(Math.max(0,r.stage),maxStage(d,id,completed)):0;
 d.scroll=Number.isFinite(r.scroll)?Math.min(Math.max(0,r.scroll),100000):0;d.updatedAt=Number.isFinite(r.updatedAt)?r.updatedAt:0;return d;
}
function normalizeData(raw){
 const d=defaultData(),r=raw&&typeof raw==='object'&&raw.version===1?raw:{};
 d.completed=unique(Array.isArray(r.completed)?r.completed.filter(validIndex):[]);d.bookmarks=unique(Array.isArray(r.bookmarks)?r.bookmarks.filter(validBookmark):[]);
 d.mistakes=unique(Array.isArray(r.mistakes)?r.mistakes.filter(validIndex):[]);d.visits=unique(Array.isArray(r.visits)?r.visits.filter(x=>typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x)):[]);d.last=validIndex(r.last)?r.last:0;
 const s=r.settings&&typeof r.settings==='object'?r.settings:{};for(const k of ['pinyin','reduced','day','large'])if(typeof s[k]==='boolean')d.settings[k]=s[k];if([.65,.85,1].includes(s.rate))d.settings.rate=s.rate;if(['gentle','challenge'].includes(s.challenge))d.settings.challenge=s.challenge;d.reviews=normalizeReviews(r.reviews,CHAPTERS);d.knowledge=normalizeKnowledgeProgress(r.knowledge);if(typeof s.voiceURI==='string'&&s.voiceURI.length<600)d.settings.voiceURI=s.voiceURI;
 const cursor=r.knowledgeCursor,topic=KNOWLEDGE_TOPICS.find(t=>t.id===cursor?.topic);if(topic)d.knowledgeCursor={topic:topic.id,item:topic.items.some(x=>x.id===cursor.item)?cursor.item:topic.items[0].id,year:Number.isInteger(cursor.year)?Math.max(1000,Math.min(1250,cursor.year)):1120};
 if(r.drafts&&typeof r.drafts==='object')for(const[id,value]of Object.entries(r.drafts)){const n=Number(id);if(validIndex(n))d.drafts[n]=normalizeDraft(value,n,d.completed)}return d;
}
let data=defaultData(),persist=true,world,current=0,draft=null,themeIndex=0;
let activeDialog=null,dialogHistory=[],filterBookmarks=false,bookScroll=0,curriculumTheme='all',curriculumStatus='all',curriculumScroll=0;
let toastTimer,speechState='idle',activeSpeechButton=null;
let reviewSession=null,knowledgeUI=null,paperCourse=0,paperVerse=0;
const narrator=createNarrator({getRate:()=>data.settings.rate,getVoiceURI:()=>data.settings.voiceURI,onState:({state,message})=>setSpeechState(state,message),onSegment:id=>$$('[data-speech-id]').forEach(el=>el.classList.toggle('speaking-segment',el.dataset.speechId===id))});
let recoveredStorage=false;
try{
 const stored=localStorage.getItem(STORAGE);
 if(stored!==null){
  try{
   const raw=JSON.parse(stored);
   recoveredStorage=!raw||typeof raw!=='object'||raw.version!==1||['completed','bookmarks','mistakes','visits'].some(k=>raw[k]!==undefined&&!Array.isArray(raw[k]));
   if(!recoveredStorage){recoveredStorage=(raw.completed||[]).some(i=>!validIndex(i))||(raw.bookmarks||[]).some(k=>!validBookmark(k))||(raw.mistakes||[]).some(i=>!validIndex(i))||(raw.last!==undefined&&!validIndex(raw.last));}
   data=normalizeData(raw);
  }catch{recoveredStorage=true}
 }
}catch{}

function shuffled(a){const r=[...a];for(let i=r.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[r[i],r[j]]=[r[j],r[i]]}return r}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(data))}catch{if(persist){persist=false;toast('当前浏览器无法保存；离开前请在设置中导出记录。')}}updateHome()}
function checkpoint(){if(draft){if(activeDialog==='#lessonDialog'&&draft.stage===0)draft.scroll=$('#lessonBody').scrollTop;draft.updatedAt=Date.now();data.drafts[current]=draft}save()}
function mountToast(){const host=activeDialog?$(activeDialog):document.body;if(host&&$('#toast').parentElement!==host)host.appendChild($('#toast'))}
function toast(message,action){mountToast();const t=$('#toast');t.replaceChildren();const span=document.createElement('span');span.textContent=message;t.appendChild(span);if(action){const b=document.createElement('button');b.className='toast-action';b.textContent=action.label;b.onclick=()=>{action.run();t.classList.remove('show')};t.appendChild(b)}t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),action?7000:4500)}
function recommended(){if(validIndex(data.last)&&!data.completed.includes(data.last))return data.last;return CHAPTERS.find(c=>!data.completed.includes(c.id))?.id??0}
function updateHome(){
 const n=data.completed.length,id=recommended(),d=data.drafts[id],started=Boolean(d||n);$('#homeCount').textContent=`${n} / ${CHAPTERS.length} 课`;
 $('#homeProgress').textContent=n===CHAPTERS.length?'六境皆通 · 温故知新':n?'已点亮 '+n+' 盏书灯':'初入书院';$('#homeBar').style.width=`${n/CHAPTERS.length*100}%`;
 $('#start').innerHTML=(n===CHAPTERS.length?'再读一小段':started?'接着上次学':'今天读一小段')+' <span>↗</span>';
 if($('#resumeHint'))$('#resumeHint').textContent=`第 ${String(id+1).padStart(2,'0')} 课 · ${CHAPTERS[id].title}${d&&!data.completed.includes(id)?' · '+stepNames[d.stage]+(d.stage===1?` ${d.recallIndex+1}/${d.recallAnswers.length}`:''):' · 约 '+Math.min(6,Math.max(3,CHAPTERS[id].verses.length+1))+' 分钟'}`;
 $('#progressDot').classList.toggle('visible',n>0);const due=getReviewQueue(data.reviews,CHAPTERS);$('#reviewHome').hidden=!due.length;$('#reviewHome').textContent=`再想一想 · ${due.length} 个小练习`;renderDock();
}
function renderDock(){$('#dock').innerHTML=names.map((name,t)=>{const list=CHAPTERS.filter(c=>c.theme===t),done=list.filter(c=>data.completed.includes(c.id)).length;return `<button class="dock-item ${t===themeIndex?'active':''}" data-theme="${t}" aria-label="查看${name}课程，${done}/${list.length}课"><span class="dock-number">第 ${t+1} 境</span><div class="dock-title">${name}</div><span class="dock-sub">${places[t]} · ${done}/${list.length} 课</span></button>`}).join('')}
function focusTheme(t){themeIndex=t;$('#worldName').textContent=names[t]+' · '+places[t];$('#worldDesc').textContent=descriptions[t];renderDock();world?.setChapter(current,t)}
function syncScenePause(){world?.setPaused?.(Boolean(activeDialog||document.hidden));knowledgeUI?.syncVisibility(activeDialog==='#knowledgeDialog'&&!document.hidden)}
function rememberView(){if(activeDialog==='#lessonDialog')checkpoint();if(activeDialog==='#bookDialog')bookScroll=$('#bookList').scrollTop;if(activeDialog==='#curriculumDialog')curriculumScroll=$('#curriculumList').scrollTop}
function showDialog(id,{push=true,remember=true}={}){
 if(!$(id))return;if(activeDialog===id){mountToast();return}const previous=activeDialog,focus=document.activeElement;
 if(remember)rememberView();stopSpeech();document.body.appendChild($('#toast'));
 if(previous){$(previous).close();if(push){dialogHistory=dialogHistory.filter(x=>x.id!==id);dialogHistory.push({id:previous,focus});dialogHistory=dialogHistory.slice(-5)}}
 activeDialog=id;$(id).showModal();mountToast();syncScenePause();updateNavigation();
 const parent=dialogHistory.at(-1)?.id,close=$(id).querySelector('[data-close]');
 if(close)close.setAttribute('aria-label',parent==='#lessonDialog'?'返回当前课程':parent==='#bookDialog'?'返回全文书卷':parent==='#reviewDialog'?'返回复习':parent==='#curriculumDialog'?'返回课程目录':parent==='#progressDialog'?'返回我的足迹':parent==='#familyDialog'?'返回陪学提示':parent==='#knowledgeDialog'?'返回动手看看':parent==='#paperDialog'?'返回活动卡':'关闭'+({'#lessonDialog':'课程','#bookDialog':'全文书卷','#curriculumDialog':'课程目录','#progressDialog':'我的足迹','#settingsDialog':'设置','#reviewDialog':'复习','#familyDialog':'陪学提示','#knowledgeDialog':'动手看看','#paperDialog':'活动卡'}[id]||'窗口'));
}
function closeDialog(dialog,{returnToOrigin=true}={}){
 if(!dialog?.open)return;rememberView();stopSpeech();document.body.appendChild($('#toast'));dialog.close();activeDialog=null;const prior=returnToOrigin?dialogHistory.pop():null;
 if(prior){if(prior.id==='#bookDialog')renderBook({preserveScroll:true});if(prior.id==='#curriculumDialog')renderCurriculum({preserveScroll:true});if(prior.id==='#progressDialog')renderProgress();if(prior.id==='#reviewDialog')renderReview();if(prior.id==='#lessonDialog'&&!draft)draft=data.drafts[current]||emptyDraft(current);showDialog(prior.id,{push:false,remember:false});if(prior.id==='#lessonDialog')renderLesson({preserveScroll:true});requestAnimationFrame(()=>{if(prior.focus?.isConnected)prior.focus.focus()})}
 else{dialogHistory=[];$('#start').focus();syncScenePause();updateNavigation();mountToast()}
}
function goHome(){rememberView();stopSpeech();document.body.appendChild($('#toast'));$$('dialog[open]').forEach(d=>d.close());dialogHistory=[];activeDialog=null;syncScenePause();updateNavigation();world?.reset();$('#start').focus()}
function updateNavigation(){const selected=activeDialog==='#bookDialog'?'library':activeDialog==='#progressDialog'?'progress':'journey';$$('.nav').forEach(b=>{const on=b.id===selected;b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')})}
$$('[data-close]').forEach(b=>b.onclick=()=>closeDialog(b.closest('dialog')));
$$('dialog').forEach(d=>{d.addEventListener('cancel',e=>{e.preventDefault();closeDialog(d)});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)}})});
function pinyinParts(v){return v.pinyin?.split(/[，。！？；,.;!?]/).map(s=>s.trim()).filter(Boolean)||[]}
function verseHTML(v){const ps=pinyinParts(v),parts=v.text.match(/[^，。！？；,.;!?]+[，。！？；,.;!?]?/g)||[v.text];return parts.map((s,i)=>`<ruby>${esc(s)}<rt>${esc(ps[i]||'')}</rt></ruby>`).join('')}
const keyFor=(c,v)=>`${c}:${v}`;
function bookmarkButton(c,i){const key=keyFor(c,i),on=data.bookmarks.includes(key);return `<button class="bookmark-btn" data-bookmark="${key}" aria-label="${on?'取消收藏':'收藏此段'}" aria-pressed="${on}">${on?'★':'☆'}</button>`}
function verseBlock(v,c,i){return `<article class="verse-block">${bookmarkButton(c,i)}<div class="verse">${verseHTML(v)}</div><p class="explanation">${esc(v.explanation)}</p>${v.note?`<p class="modern-note">今读提示 · ${esc(v.note)}</p>`:''}</article>`}
function syncBookmarkButtons(){$$('[data-bookmark]').forEach(b=>{const on=data.bookmarks.includes(b.dataset.bookmark);b.textContent=on?'★':'☆';b.setAttribute('aria-pressed',on);b.setAttribute('aria-label',on?'取消收藏':'收藏此段')})}
function toggleBookmark(key){const removing=data.bookmarks.includes(key);data.bookmarks=removing?data.bookmarks.filter(x=>x!==key):[...data.bookmarks,key];save();syncBookmarkButtons();if(activeDialog==='#bookDialog')renderBook({preserveScroll:true});toast(removing?'已取消收藏。':'已收入收藏。',removing?{label:'撤销',run:()=>{if(!data.bookmarks.includes(key))data.bookmarks.push(key);save();syncBookmarkButtons();if(activeDialog==='#bookDialog')renderBook({preserveScroll:true})}}:undefined)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-bookmark]');if(b)toggleBookmark(b.dataset.bookmark);const go=e.target.closest('[data-open]');if(go)openLesson(Number(go.dataset.open));const theme=e.target.closest('[data-theme]');if(theme){const t=Number(theme.dataset.theme);focusTheme(t);showCurriculum(t)}const lab=e.target.closest('[data-knowledge]');if(lab)knowledgeUI.open(lab.dataset.knowledge);const paper=e.target.closest('[data-paper]');if(paper)showActivitySheet(Number(paper.dataset.paper),draft?.stage===0?draft.readIndex:0);const say=e.target.closest('[data-say]');if(say){if(activeDialog==='#lessonDialog'&&draft?.stage===2&&!draft.orderSolved){draft.orderHelp=true;recordAttempt(`${current}:${current%CHAPTERS[current].verses.length}`,false,true);checkpoint()}speak(say.dataset.say,say,say.dataset.segment||null);}const pin=e.target.closest('[data-pinyin]');if(pin){data.settings.pinyin=!data.settings.pinyin;applySettings();save()}});
document.addEventListener('toggle',e=>{if(activeDialog!=='#lessonDialog'||!e.target.matches?.('.reference-sheet')||!e.target.open||!draft)return;let key;if(draft.stage===1&&!draft.recallAnswers[draft.recallIndex]){draft.recallHelp[draft.recallIndex]=true;key=`${current}:${draft.recallIndex}`}else if(draft.stage===2&&!draft.orderSolved){draft.orderHelp=true;key=`${current}:${current%CHAPTERS[current].verses.length}`}else if(draft.stage===3&&!draft.quizSolved){draft.quizHelp=true;key=`${current}:q`}if(key){recordAttempt(key,false,true);checkpoint()}},true);
function showCurriculum(theme){if(theme!==undefined){curriculumTheme=theme;curriculumStatus='all';$('#curriculumSearch').value='';curriculumScroll=0}renderCurriculum({preserveScroll:true});showDialog('#curriculumDialog');$('#curriculumList').scrollTop=curriculumScroll}
function renderCurriculum({preserveScroll=false}={}){
 if(!$('#curriculumList'))return;const old=preserveScroll?(activeDialog==='#curriculumDialog'?$('#curriculumList').scrollTop:curriculumScroll):0,q=normalizeSearch($('#curriculumSearch').value);
 $('#curriculumFilters').innerHTML=`<div class="curriculum-filter-group" aria-label="按主题筛选"><button class="filter-chip" data-curr-theme="all" aria-pressed="${curriculumTheme==='all'}">全部六境</button>${names.map((n,i)=>`<button class="filter-chip" data-curr-theme="${i}" aria-pressed="${curriculumTheme===i}">${n}</button>`).join('')}</div><div class="curriculum-filter-group" aria-label="按学习状态筛选">${[['all','全部进度'],['new','未开始'],['active','进行中'],['done','已完成']].map(([key,label])=>`<button class="filter-chip" data-curr-status="${key}" aria-pressed="${curriculumStatus===key}">${label}</button>`).join('')}</div>`;
 const status=c=>data.completed.includes(c.id)?'done':data.drafts[c.id]?'active':'new';
 const list=CHAPTERS.filter(c=>(curriculumTheme==='all'||c.theme===curriculumTheme)&&(curriculumStatus==='all'||status(c)===curriculumStatus)&&(!q||normalizeSearch([c.title,c.subtitle,...c.verses.map(v=>v.text)].join('')).includes(q)));
 $('#curriculumSummary').textContent=`40 课 · 当前 ${list.length} 课 · ${data.completed.length} 课已完成。可按顺序学习，也可自由选课。`;
 $('#curriculumList').innerHTML=list.length?names.map((n,t)=>{const courses=list.filter(c=>c.theme===t);return courses.length?`<section class="curriculum-section"><h3 class="curriculum-section-title">${t+1} · ${n}<small>${places[t]} · ${descriptions[t]}</small></h3><div class="curriculum-grid curriculum-cards">${courses.map(c=>{const state=status(c),d=data.drafts[c.id],label=state==='done'?'已完成':state==='active'?'继续 · '+stepNames[d.stage]:'未开始';return `<button class="curriculum-card ${state}" data-open="${c.id}"><span class="curriculum-card-meta">第 ${String(c.id+1).padStart(2,'0')} 课 · ${c.verses.length} 段 · 约 ${Math.min(6,Math.max(3,c.verses.length+1))} 分钟</span><h3>${esc(c.title)}</h3><p class="curriculum-card-preview">${esc(c.verses[0].text)}</p><span class="curriculum-card-status">${state==='done'?'✓':state==='active'?'◐':'○'} ${esc(label)}<i>→</i></span></button>`}).join('')}</div></section>`:''}).join(''):'<div class="curriculum-empty empty">没有符合当前条件的课程。<br>试试其他关键词，或清除筛选。<button class="outline-btn" id="clearCurriculumFilters">清除筛选</button></div>';
 $$('[data-curr-theme]').forEach(b=>b.onclick=()=>{curriculumTheme=b.dataset.currTheme==='all'?'all':Number(b.dataset.currTheme);renderCurriculum()});$$('[data-curr-status]').forEach(b=>b.onclick=()=>{curriculumStatus=b.dataset.currStatus;renderCurriculum()});if($('#clearCurriculumFilters'))$('#clearCurriculumFilters').onclick=()=>{curriculumTheme='all';curriculumStatus='all';$('#curriculumSearch').value='';renderCurriculum()};$('#curriculumList').scrollTop=old;curriculumScroll=old;
}
function openLesson(id){
 if(!validIndex(id))return;rememberView();current=id;data.last=id;draft=data.drafts[id]?normalizeDraft(data.drafts[id],id,data.completed):emptyDraft(id);if(draft.stage===4)draft.stage=0;
 const day=new Date(),date=`${day.getFullYear()}-${String(day.getMonth()+1).padStart(2,'0')}-${String(day.getDate()).padStart(2,'0')}`;if(!data.visits.includes(date))data.visits.push(date);
 data.drafts[id]=draft;focusTheme(CHAPTERS[id].theme);showDialog('#lessonDialog',{remember:false});renderLesson({preserveScroll:true});checkpoint();
}

function pinyinControl(){return `<button class="outline-btn inline-pinyin" data-pinyin aria-pressed="${data.settings.pinyin}">${data.settings.pinyin?'隐藏拼音':'显示拼音'}</button>`}
function guide(id=current){return CHILD_GUIDES[id]}
function childVerse(id,i){return guide(id).verses[i]}
function listenButton(text,label='听一听',segment=''){return `<button class="outline-btn listen-btn" data-say="${esc(text)}" data-segment="${esc(segment)}" aria-pressed="false">▷ ${label}</button>`}
function phraseHTML(text,id=current){for(const v of CHAPTERS[id].verses){const a=chunks(v),i=a.indexOf(text);if(i>=0)return `<ruby>${esc(text)}<rt>${esc(pinyinParts(v)[i]||'')}</rt></ruby>`}return esc(text)}
function referenceHTML(){const c=CHAPTERS[current];return `<details class="reference-sheet"><summary>看看本课原文 <span>答案不会丢</span></summary><div class="reference-content">${c.verses.map((v,i)=>verseBlock(v,current,i)).join('')}</div></details>`}
function lessonToolbar(){return `<div class="lesson-toolbar"><span class="lesson-save-status">${persist?'可以慢慢想，也可以随时休息':'请大人帮忙导出记录'}</span>${pinyinControl()}</div><div id="speechStatus" class="speech-status" role="status"></div>`}
function setStage(stage){if(stage<0||stage>maxStage(draft,current,data.completed))return;draft.stage=stage;draft.scroll=0;checkpoint();renderLesson()}
function syncMistakes(){for(const c of CHAPTERS){const entries=Object.entries(data.reviews).filter(([key])=>key.startsWith(c.id+':')).map(([,r])=>r);if(entries.some(r=>r.lastResult==='retry'||r.lastResult==='helped')){if(!data.mistakes.includes(c.id))data.mistakes.push(c.id)}else if(entries.length>=c.verses.length+1)data.mistakes=data.mistakes.filter(id=>id!==c.id)}}
function recordAttempt(key,success,helped=false,isReview=false){recordReview(data.reviews,key,{success,helped,day:localDay(),isReview});syncMistakes();save()}
function renderLesson({preserveScroll=false}={}){
 stopSpeech();const c=CHAPTERS[current],body=$('#lessonBody'),scroll=preserveScroll&&draft.stage===0?draft.scroll:0;
 $('#lessonMeta').textContent=`${names[c.theme]} · 第 ${current+1} 课`;$('#lessonTitle').textContent=c.title;$('#lessonSection').textContent=places[c.theme]+' · '+descriptions[c.theme];
 $('#lessonChapters').innerHTML=CHAPTERS.filter(x=>x.theme===c.theme).map(x=>`<button data-open="${x.id}" class="${x.id===current?'active':''}" ${x.id===current?'aria-current="step"':''}><span>${String(x.id+1).padStart(2,'0')}</span>${esc(x.title)}${data.completed.includes(x.id)?'<b>✓</b>':data.drafts[x.id]?'<b>◐</b>':''}</button>`).join('');
 const reached=maxStage(draft,current,data.completed);$('#steps').innerHTML=stepNames.slice(0,4).map((name,i)=>`${i?'<i class="step-line"></i>':''}<button class="step step-button ${draft.stage===i?'active':''} ${reached>i?'done':''}" data-step="${i}" ${i>reached?'disabled':''} ${draft.stage===i?'aria-current="step"':''} aria-label="${i>reached?'完成前一步后解锁：':'查看：'}${name}"><b>${reached>i?'✓':i+1}</b>${name}</button>`).join('');
 $$('[data-step]').forEach(b=>b.onclick=()=>setStage(Number(b.dataset.step)));$('#lessonFooter').innerHTML='';
 if(draft.stage===0)renderReading();if(draft.stage===1)renderRecall();if(draft.stage===2)renderOrder();if(draft.stage===3)renderQuiz();if(draft.stage===4)renderComplete();body.scrollTop=scroll;
}
function relatedKnowledge(id,vi){const topic=KNOWLEDGE_TOPICS.find(t=>t.verseLinks.some(v=>v.chapterId===id&&v.verseIndex===vi));return topic?`<aside class="lesson-discover"><p>${esc(topic.goal)}</p><button class="outline-btn" data-knowledge="${topic.id}">动手看看 →</button></aside>`:''}
function renderReading(){
 const c=CHAPTERS[current],i=draft.readIndex,v=c.verses[i],g=guide(),small=childVerse(current,i),segment=`read-${current}-${i}`;
 $('#lessonBody').innerHTML=`<div class="reading-way"><span>第 ${i+1} / ${c.verses.length} 小段</span><span>${data.settings.challenge==='gentle'?'轻松学 · 两个选项':'自己挑战 · 四个选项'}</span></div><p class="child-goal">这次试着：${esc(g.goal)}</p><div class="lesson-quick-tools">${listenButton(v.text,'听这一段',segment)}${listenButton(v.text+'。读懂这一段，我们可以这样理解：'+small.plain,'听原文和解释',segment)}${pinyinControl()}</div><div id="speechStatus" class="speech-status" role="status"></div><article class="focus-verse" data-speech-id="${segment}">${bookmarkButton(current,i)}<div class="verse">${verseHTML(v)}</div><p class="child-plain-label">读懂这一段</p><p class="child-plain">${esc(small.plain)}</p></article><div class="word-help"><span>点开词语看看</span>${small.words.map(w=>`<details class="word-chip"><summary>${esc(w.term)}</summary><div>${esc(w.meaning)} ${listenButton(w.term+'。'+w.meaning,'听词语')}</div></details>`).join('')}</div><details class="reading-detail"><summary>多了解一点</summary><p>${esc(v.explanation)}</p>${v.note?`<p class="modern-note">${esc(v.note)}</p>`:''}</details>${relatedKnowledge(current,i)}<details class="family-card"><summary>一起说一说</summary><p>${esc(g.talk)}</p>${listenButton(g.talk,'听问题')}<small>可以说给陪学的大人听，也可以自己想一想；不用输入答案。</small></details><button class="text-link lesson-paper" data-paper="${current}">把这一段变成活动卡 ↗</button>`;
 $('#lessonFooter').innerHTML=`<button class="text-link" id="previousReading" ${i===0?'disabled':''}>← 上一段</button><button class="primary" id="nextStep">${i<c.verses.length-1?'读下一小段':'读好了，试一试'} →</button>`;
 $('#previousReading').onclick=()=>{stopSpeech();draft.readIndex--;draft.scroll=0;$('#lessonBody').scrollTop=0;checkpoint();renderReading();$('#lessonBody').scrollTop=0};
 $('#nextStep').onclick=()=>{stopSpeech();draft.readSeen=unique([...draft.readSeen,i]);if(i<c.verses.length-1){draft.readIndex++;draft.scroll=0;$('#lessonBody').scrollTop=0;checkpoint();renderReading();$('#lessonBody').scrollTop=0}else{draft.readDone=true;const pending=draft.recallAnswers.findIndex(v=>!v);if(pending>=0)draft.recallIndex=pending;setStage(1)}};
}
function markMistake(verse){if(!data.mistakes.includes(current))data.mistakes.push(current);recordAttempt(verse===undefined?`${current}:q`:`${current}:${verse}`,false);checkpoint()}
function recallChoicesFor(c,i,count){const parts=chunks(c.verses[i]),answer=parts[(i+1)%parts.length];const pool=unique([...parts,...c.verses.flatMap(chunks)]).filter(x=>x!==answer);return shuffled([answer,...shuffled(pool).slice(0,count-1)])}
function renderRecall(){
 stopSpeech();const c=CHAPTERS[current],i=draft.recallIndex,v=c.verses[i],parts=chunks(v),blank=(i+1)%parts.length,answer=parts[blank],count=data.settings.challenge==='gentle'?2:4;
 if(!draft.recallChoices[i]||draft.recallChoices[i].length!==count){draft.recallChoices[i]=recallChoicesFor(c,i,count);checkpoint()}
 const choices=draft.recallChoices[i],solved=draft.recallAnswers[i],hint=Boolean(draft.recallHelp[i]),spoken=parts.map((x,n)=>n===blank?'这里空着':x).join('，')+'。选项是：'+choices.join('，或，');
 $('#lessonBody').innerHTML=`${lessonToolbar()}<div class="challenge-label">补一句 · ${i+1} / ${c.verses.length}</div><h3 class="challenge-title">空着的地方，接哪一句？</h3><div class="question-tools">${listenButton(spoken,'听题目与选项')}<button class="outline-btn" id="recallHint">${hint?'提示已打开':'给我一个提示'}</button></div><div class="challenge-verse">${parts.map((s,k)=>k===blank?`<span class="blank">${solved?phraseHTML(answer):'？'}</span>`:phraseHTML(s)).join('，')}。</div><div class="options ${count===2?'two-options':''}">${choices.map((s,k)=>`<button class="answer-option ${solved&&s===answer?'correct':''} ${draft.recallWrong[i]?.includes(s)?'wrong':''}" data-answer="${k}" ${solved||draft.recallWrong[i]?.includes(s)?'disabled':''}><span class="choice-marker">${solved&&s===answer?'✓':k+1}</span>${phraseHTML(s)}</button>`).join('')}</div><div class="feedback ${solved?'success':''}" role="status" id="feedback">${solved?'✓ 找对了！'+esc(childVerse(current,i).plain):''}</div>${hint?`<aside class="gentle-hint"><b>一起读一遍</b><p>${esc(v.text)}</p>${listenButton(v.text,'听示范')}<small>看过提示也没关系，我们改天再试一次。</small></aside>`:''}${referenceHTML()}`;
 $('#lessonFooter').innerHTML=`<button class="text-link" id="previousRecall" ${i===0?'disabled':''}>← 上一段</button><button class="primary" id="nextRecall" ${solved?'':'disabled'}>${i===c.verses.length-1?'去拼一拼':'下一段'} →</button>`;
 $('#recallHint').disabled=solved;$('#recallHint').onclick=()=>{if(draft.recallAnswers[i])return;draft.recallHelp[i]=true;recordAttempt(`${current}:${i}`,false,true);checkpoint();renderRecall()};
 $('#previousRecall').onclick=()=>{draft.recallIndex--;checkpoint();renderRecall();$('#lessonBody').scrollTop=0};
 $$('[data-answer]').forEach(b=>b.onclick=()=>{if(draft.recallAnswers[i])return;const correct=choices[Number(b.dataset.answer)]===answer;if(correct){draft.recallAnswers[i]=true;recordAttempt(`${current}:${i}`,true,!!draft.recallHelp[i]||Boolean(draft.recallWrong[i]?.length));checkpoint();renderRecall();chime();$('#nextRecall').focus()}else{draft.recallWrong[i]=unique([...(draft.recallWrong[i]||[]),choices[Number(b.dataset.answer)]]);draft.recallHelp[i]=true;markMistake(i);renderRecall();$('#feedback').textContent=`还没接上。看看下面的完整句子，再选一次。`;$('#recallHint').focus()}});
 $('#nextRecall').onclick=()=>{if(!draft.recallAnswers[i])return;if(i<c.verses.length-1){draft.recallIndex++;checkpoint();renderRecall();$('#lessonBody').scrollTop=0}else if(draft.recallAnswers.every(Boolean))setStage(2)};
}
function renderOrder(){
 stopSpeech();const vi=current%CHAPTERS[current].verses.length,v=CHAPTERS[current].verses[vi],parts=chunks(v);if(!draft.orderChoices.length){draft.orderChoices=shuffled([0,1,2,3]);if(draft.orderChoices.every((v,i)=>v===i))draft.orderChoices.reverse();checkpoint()}
 $('#lessonBody').innerHTML=`${lessonToolbar()}<div class="challenge-label">拼一拼</div><h3 class="challenge-title">按顺序，把四句连起来。</h3><p class="muted">点下面的字牌放进去。点上面的字牌可以拿回来。</p><div class="question-tools">${listenButton(v.text,'听这一段')}<button class="outline-btn" id="orderHint">帮我接下一句</button></div><div id="orderSlots" class="order-slots"></div><div class="order-options" id="orderChoices"></div><div class="feedback ${draft.orderSolved?'success':''}" role="status" id="feedback">${draft.orderSolved?'✓ 接好了！一起把整段读一遍。':''}</div>${draft.orderHelp?'<p class="gentle-hint">我们一起接过这段，改天再自己试一试。</p>':''}${referenceHTML()}`;
 $('#lessonFooter').innerHTML='<button class="text-link" id="resetOrder">重新排列</button><button class="primary" id="checkOrder"></button>';
 $('#resetOrder').onclick=()=>{draft.order=[];draft.orderSolved=false;draft.quizSolved=false;checkpoint();renderOrder()};
 $('#orderHint').disabled=draft.orderSolved;$('#orderHint').onclick=()=>{if(draft.orderSolved)return;draft.orderHelp=true;let n=0;while(n<draft.order.length&&parts[draft.order[n]]===parts[n])n++;draft.order=draft.order.slice(0,n);if(n<4)draft.order.push(n);recordAttempt(`${current}:${vi}`,false,true);checkpoint();renderOrder();$('#feedback').textContent='保留了接对的部分，又帮你接好一句。现在接着试试。'};
 $('#checkOrder').onclick=()=>{if(draft.orderSolved){setStage(3);return}if(draft.order.length!==parts.length)return;if(draft.order.every((id,i)=>parts[id]===parts[i])){draft.orderSolved=true;recordAttempt(`${current}:${vi}`,true,draft.orderHelp);checkpoint();renderOrder();chime();$('#checkOrder').focus()}else{draft.orderHelp=true;markMistake(vi);let n=0;while(n<draft.order.length&&parts[draft.order[n]]===parts[n])n++;$('#feedback').textContent=`前 ${n} 句已接好。第 ${n+1} 句需要再想想，可以点“帮我接下一句”。`;$('#orderHint').focus()}};
 const draw=()=>{$('#orderSlots').innerHTML=parts.map((s,i)=>`<button class="order-slot ${draft.order[i]!==undefined?'filled':''}" data-slot="${i}" ${draft.orderSolved||draft.order[i]===undefined?'disabled':''} aria-label="${draft.order[i]!==undefined?'拿回 '+parts[draft.order[i]]:'第'+(i+1)+'个空位'}">${draft.order[i]!==undefined?phraseHTML(parts[draft.order[i]]):`<small>${i+1}</small>`}</button>`).join('');
 $('#orderChoices').innerHTML=draft.orderChoices.map(id=>`<button data-piece="${id}" ${draft.orderSolved||draft.order.includes(id)?'disabled':''}>${phraseHTML(parts[id])}</button>`).join('');
 $$('[data-piece]').forEach(b=>b.onclick=()=>{draft.order.push(Number(b.dataset.piece));checkpoint();draw()});$$('[data-slot]').forEach(b=>b.onclick=()=>{draft.order.splice(Number(b.dataset.slot),1);checkpoint();draw()});$('#checkOrder').disabled=draft.order.length!==parts.length;$('#checkOrder').textContent=draft.orderSolved?'去想一想 →':'拼好了吗？ →';};draw();
}
function renderQuiz(){
 stopSpeech();const q=CHAPTERS[current].quiz,ids=data.settings.challenge==='gentle'?[q.answer,(q.answer+1)%q.options.length].sort((a,b)=>a-b):q.options.map((_,i)=>i);
 $('#lessonBody').innerHTML=`${lessonToolbar()}<div class="challenge-label">想一想</div><h3 class="challenge-title">${esc(q.question)}</h3><div class="question-tools">${listenButton(q.question+'。'+ids.map((id,i)=>`选项${i+1}，${q.options[id]}`).join('。'),'听题目与选项')}<button class="outline-btn" id="quizHint">一起想一想</button></div><div class="options ${ids.length===2?'two-options':''}">${ids.map((i,k)=>`<button class="answer-option ${draft.quizSolved&&i===q.answer?'correct':''} ${draft.quizWrong.includes(i)?'wrong':''}" data-quiz="${i}" ${draft.quizSolved||draft.quizWrong.includes(i)?'disabled':''}><span class="choice-marker">${draft.quizSolved&&i===q.answer?'✓':k+1}</span>${esc(q.options[i])}</button>`).join('')}</div><div class="feedback ${draft.quizSolved?'success':''}" role="status" id="feedback">${draft.quizSolved?'✓ '+esc(q.explanation):''}</div>${draft.quizHelp?`<aside class="gentle-hint"><p>${esc(q.explanation)}</p>${listenButton(q.explanation,'听提示')}</aside>`:''}${referenceHTML()}`;
 $('#quizHint').disabled=draft.quizSolved;$('#quizHint').onclick=()=>{if(draft.quizSolved)return;draft.quizHelp=true;recordAttempt(`${current}:q`,false,true);checkpoint();renderQuiz()};
 $('#lessonFooter').innerHTML=`<span class="lesson-save-status">读懂意思就很好</span><button class="primary" id="completeLesson" ${draft.quizSolved?'':'disabled'}>点亮小书灯 ✦</button>`;
 $$('[data-quiz]').forEach(b=>b.onclick=()=>{if(draft.quizSolved)return;if(Number(b.dataset.quiz)===q.answer){draft.quizSolved=true;recordAttempt(`${current}:q`,true,draft.quizHelp||Boolean(draft.quizWrong.length));checkpoint();renderQuiz();chime();$('#completeLesson').focus()}else{draft.quizWrong=unique([...draft.quizWrong,Number(b.dataset.quiz)]);draft.quizHelp=true;markMistake();renderQuiz();$('#feedback').textContent='我们换个想法。先听听提示，再选一次。';$('#quizHint').focus()}});
 $('#completeLesson').onclick=()=>{if(!draft.quizSolved||!draft.orderSolved||!draft.recallAnswers.every(Boolean))return;if(!data.completed.includes(current))data.completed.push(current);draft.stage=4;checkpoint();world?.celebrate();renderLesson()};
}
function renderComplete(){
 const total=data.completed.length,c=CHAPTERS[current],g=guide(),helped=Object.values(draft.recallHelp).some(Boolean)||draft.orderHelp||draft.quizHelp;
 $('#lessonBody').innerHTML=`<div class="complete"><div class="big-seal">完成</div><h3>这一步，你走到了。</h3><p>读过、试过，也想过。<br>「${esc(c.title)}」的小书灯亮起来了。</p><div class="reward"><span>✦ 已完成 ${total} 课</span><span>${helped?'一起完成，也值得记录':'这次自己试出来了'}</span></div><p class="muted">完成练习不等于一直记住，改天可以再想一句。</p></div><section class="offline-activity"><span>离开屏幕，也能学</span><h3>试着做一件小事</h3><p>${esc(g.activity)}</p>${listenButton(g.activity,'听听怎么做')}</section>`;
 $('#lessonFooter').innerHTML=`<button class="primary" id="backHome">今天学到这里</button><button class="outline-btn" id="nextLesson">${current<39?'我还想学 →':'看看我的足迹 →'}</button>`;$('#backHome').onclick=goHome;$('#nextLesson').onclick=()=>current<39?openLesson(current+1):showProgress();
}

function renderBook({preserveScroll=false}={}){
 const old=preserveScroll?(activeDialog==='#bookDialog'?$('#bookList').scrollTop:bookScroll):0,query=normalizeSearch($('#search').value);let count=0;
 $('#bookList').innerHTML=CHAPTERS.map(c=>{const verses=c.verses.map((v,i)=>({v,i})).filter(({v,i})=>(!filterBookmarks||data.bookmarks.includes(keyFor(c.id,i)))&&(!query||normalizeSearch([v.text,v.explanation,v.note,c.title,v.pinyin].join('')).includes(query)));count+=verses.length;return verses.length?`<section class="book-chapter"><div class="book-chapter-head"><h3>${String(c.id+1).padStart(2,'0')} · ${esc(c.title)}</h3><button class="text-link" data-open="${c.id}">${data.drafts[c.id]&&!data.completed.includes(c.id)?'继续本课':'进入学习'} →</button></div>${verses.map(({v,i})=>verseBlock(v,c.id,i)).join('')}</section>`:''}).join('');
 if(!count)$('#bookList').innerHTML=`<div class="empty">${filterBookmarks&&!data.bookmarks.length?'还没有收藏。<br>点击原文旁的 ☆，把喜欢的段落收进这里。':query?'没有找到匹配的内容。<br>试试课名、连续原文或不带声调的拼音。':'当前筛选没有结果。'}<button class="outline-btn" id="clearBookFilter">查看全部原文</button></div>`;
 if($('#clearBookFilter'))$('#clearBookFilter').onclick=()=>{$('#search').value='';filterBookmarks=false;$('#bookmarkFilter').setAttribute('aria-pressed','false');renderBook()};
 $('#bookSummary').textContent=`全文 120 段 · ${filterBookmarks?'已收藏 '+data.bookmarks.length+' 段 · ':''}当前显示 ${count} 段`;
 $('#bookSource').innerHTML=`版本：${esc(META.version)}。按所选底本完整收录；释义与今读提示为学习用编写。<a href="${esc(META.sourceUrl)}" target="_blank" rel="noopener noreferrer">核对原文 ↗</a>`;$('#bookList').scrollTop=old;bookScroll=old;
}
function showBook(){renderBook({preserveScroll:true});showDialog('#bookDialog');$('#bookList').scrollTop=bookScroll}
function renderProgress(){
 const n=data.completed.length,inProgress=Object.keys(data.drafts).map(Number).filter(id=>!data.completed.includes(id));
 $('#progressBody').innerHTML=`<div class="stats"><div class="stat"><strong>${n}</strong><span>已完成课程 / 40</span></div><div class="stat"><strong>${data.visits.length}</strong><span>留下足迹的日子</span></div><div class="stat"><strong>${data.bookmarks.length}</strong><span>收藏的经典段落</span></div></div>${inProgress.length?`<section class="progress-section"><h3>接着上次学</h3><div class="review-list">${inProgress.slice(-6).map(id=>`<button class="outline-btn" data-open="${id}">${esc(CHAPTERS[id].title)} · ${stepNames[data.drafts[id].stage]} →</button>`).join('')}</div></section>`:''}<section class="progress-section"><h3>六境印记</h3><div class="medals">${names.map((name,i)=>{const list=CHAPTERS.filter(c=>c.theme===i),done=list.filter(c=>data.completed.includes(c.id)).length;return `<button class="medal ${done===list.length?'earned':''}" data-theme="${i}"><b>${name}</b><small>${done}/${list.length} 课${done===list.length?' · 已通':''}</small></button>`}).join('')}</div></section><section class="progress-section"><h3>再想一句</h3><button class="outline-btn" id="openReview">${getReviewQueue(data.reviews,CHAPTERS).length?'今天有 '+getReviewQueue(data.reviews,CHAPTERS).length+' 个小练习':'看看复习安排'}</button><p class="muted" style="margin-bottom:13px">${data.mistakes.length?'这些课有需要再想一想的地方。可以点上方按句复习，也可以重新读一课。':n?'已经读懂的文字，值得时常重温。':'先读懂第一课，再慢慢点亮六境。'}</p><div class="review-list">${(data.mistakes.length?data.mistakes:data.completed.slice(-6)).map(i=>`<button class="outline-btn" data-open="${i}">${esc(CHAPTERS[i].title)} →</button>`).join('')}</div></section><section class="progress-section"><button class="primary" data-open="${recommended()}">继续我的学习 →</button><p class="muted" style="margin-top:13px">进度保存在当前浏览器。换设备时，在设置中导出记录并导入另一台设备。</p></section>`;
}
document.addEventListener('click',e=>{if(e.target.closest('#openReview'))startReview()});
function showProgress(){renderProgress();showDialog('#progressDialog')}


function startReview(all=false){const queue=getReviewQueue(data.reviews,CHAPTERS,{includeFuture:all});reviewSession={queue:queue.slice(0,3),index:0,done:0,helped:false,solved:false,choices:null,wrong:[]};renderReview();showDialog('#reviewDialog')}
function renderReview(){
 if(!reviewSession)return;const session=reviewSession,entry=session.queue[session.index],body=$('#reviewBody');stopSpeech();
 if(!entry){body.innerHTML=`<div class="complete"><div class="big-seal">歇会</div><h3>${session.done?'今天这几句，又见面了。':'今天没有要复习的句子。'}</h3><p>${session.done?`你试了 ${session.done} 个小练习。`:'可以读一小段，也可以去玩一会儿。'}</p><p class="muted">没有连续打卡要求，随时都能回来。</p><button class="primary" id="finishReview">回到书院</button>${!session.done&&Object.keys(data.reviews).length?'<button class="outline-btn" id="reviewEarly">我想提前再试一句</button>':''}</div>`;$('#finishReview').onclick=goHome;if($('#reviewEarly'))$('#reviewEarly').onclick=()=>startReview(true);return}
 const c=CHAPTERS[entry.chapterId],isQuiz=entry.verseIndex===null,v=isQuiz?null:c.verses[entry.verseIndex],parts=v?chunks(v):[],blank=v?(entry.verseIndex+1)%4:0,answer=isQuiz?c.quiz.options[c.quiz.answer]:parts[blank];
 if(!session.choices){const count=data.settings.challenge==='gentle'?2:4;session.choices=isQuiz?shuffled([answer,...c.quiz.options.filter(x=>x!==answer).slice(0,count-1)]):recallChoicesFor(c,entry.verseIndex,count)}
 const prompt=isQuiz?c.quiz.question:parts.map((s,i)=>i===blank?'这里空着':s).join('，'),explanation=isQuiz?c.quiz.explanation:childVerse(c.id,entry.verseIndex).plain;
 body.innerHTML=`<div class="reading-way"><span>再想一句 · ${session.index+1} / ${session.queue.length}</span><span>${esc(c.title)}</span></div><h3 class="challenge-title">${esc(isQuiz?prompt:'还记得这里接什么吗？')}</h3>${!isQuiz?`<div class="challenge-verse">${parts.map((s,i)=>i===blank?'<span class="blank">？</span>':phraseHTML(s,c.id)).join('，')}。</div>`:''}<div class="question-tools">${listenButton(prompt+'。选项是：'+session.choices.join('，或，'),'听题目与选项')}<button class="outline-btn" id="reviewHint">我想看提示</button></div><div id="speechStatus" class="speech-status" role="status"></div><div class="options two-options">${session.choices.map((x,i)=>`<button class="answer-option ${session.solved&&x===answer?'correct':''}" data-review-choice="${i}" ${session.solved||session.wrong.includes(x)?'disabled':''}><span class="choice-marker">${i+1}</span>${isQuiz?esc(x):phraseHTML(x,c.id)}</button>`).join('')}</div><div id="reviewFeedback" role="status" class="feedback">${session.solved?'✓ 找对了。'+esc(explanation):''}</div>${session.helped?`<aside class="gentle-hint">${esc(isQuiz?explanation:v.text)} ${listenButton(isQuiz?explanation:v.text,'听提示')}</aside>`:''}<div class="review-actions"><button class="outline-btn" id="restReview">先休息</button><button class="primary" id="nextReview" ${session.solved?'':'disabled'}>${session.index===session.queue.length-1?'今天就到这里':'下一句'} →</button></div>`;
 $('#reviewHint').disabled=session.solved;$('#reviewHint').onclick=()=>{if(session.solved)return;session.helped=true;recordAttempt(entry.key,false,true,true);renderReview()};$('#restReview').onclick=goHome;
 $$('[data-review-choice]').forEach(b=>b.onclick=()=>{if(session.solved)return;const chosen=session.choices[Number(b.dataset.reviewChoice)];if(chosen===answer){session.solved=true;session.done++;recordAttempt(entry.key,true,session.helped,true);renderReview();$('#nextReview').focus()}else{session.wrong.push(chosen);session.helped=true;recordAttempt(entry.key,false,false,true);renderReview();$('#reviewFeedback').textContent='先看看提示，过一会儿再自己想一想。'}});
 $('#nextReview').onclick=()=>{session.index++;session.helped=false;session.solved=false;session.choices=null;session.wrong=[];renderReview();body.scrollTop=0};
}
function showFamily(){
 const id=activeDialog==='#lessonDialog'?current:recommended(),g=guide(id);$('#familyBody').innerHTML=`<p class="family-intro">先听孩子怎么想，再给一点帮助。每次读一小段就可以停下来。</p><section class="family-section"><h3>这课可以怎么陪</h3><p><b>一起聊：</b>${esc(g.talk)}</p><p><b>一起做：</b>${esc(g.activity)}</p></section><section class="family-section"><h3>让孩子轻松开始</h3><ol><li>先听一段，再让孩子选想读的句子。</li><li>等孩子想一想，不急着替他回答。</li><li>答错时先听示范，再说“我们再试一次”。</li><li>请孩子用自己的话说意思；允许不同的生活例子。</li></ol></section><section class="family-section"><h3>这里的记录表示什么</h3><p>“完成”表示走过练习，不等于长期记住。看过提示、答错后再答对的内容会留下复习记录。</p><p>默认隔日再见；到期独立答对后，间隔逐步到 3 天、7 天。这只是可调整的起步规则，尚未验证本产品的学习效果。</p><p>古书中的尊卑、性别和勤学观念有时代背景。今天学习时，应尊重每个人，也保护孩子的休息与游戏。</p></section><section class="family-section"><h3>需要时再调整</h3><button class="outline-btn" id="familySettings">阅读、难度与记录设置</button><button class="outline-btn" id="familyPaper">制作本课活动卡</button><p class="muted">记录只保存在当前浏览器；不录音、不收集真实姓名。换设备可在设置中导出、合并导入。</p></section>`;$('#familySettings').onclick=()=>showDialog('#settingsDialog');$('#familyPaper').onclick=()=>showActivitySheet(id,0);showDialog('#familyDialog');
}

function setSpeechState(state,message=''){speechState=state;if(activeSpeechButton?.isConnected){if(!activeSpeechButton.dataset.originalLabel)activeSpeechButton.dataset.originalLabel=activeSpeechButton.textContent;activeSpeechButton.textContent=state==='loading'?'■ 准备中 · 点此停止':state==='speaking'?'■ 停止朗读':activeSpeechButton.dataset.originalLabel;activeSpeechButton.setAttribute('aria-pressed',state!=='idle')}const status=activeDialog?$(activeDialog)?.querySelector('#speechStatus'):null;if(status)status.textContent=message}
function stopSpeech(){narrator.stop()}
function speak(text,button=null,id=null){if(speechState!=='idle'){stopSpeech();return}activeSpeechButton=button;narrator.play([{id:id||'spoken-prompt',text}])}
let audioCtx,ambientNodes=[],soundOn=false;

function getAudio(){if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();return audioCtx}
function chime(){if(!soundOn)return;try{const ctx=getAudio(),o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(659.25,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(987.77,ctx.currentTime+.25);g.gain.setValueAtTime(.07,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+1.2);o.connect(g).connect(ctx.destination);o.start();o.stop(ctx.currentTime+1.2)}catch{}}
function toggleSound(){try{if(soundOn){ambientNodes.forEach(n=>{try{n.stop()}catch{}});ambientNodes=[];soundOn=false}else{const ctx=getAudio();[130.81,196,261.63].forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=f;g.gain.value=.008/(i+1);o.connect(g).connect(ctx.destination);o.start();ambientNodes.push(o)});soundOn=true}$('#sound').textContent=soundOn?'♪':'♫';$('#sound').setAttribute('aria-label',soundOn?'关闭环境音':'开启环境音');$('#sound').setAttribute('aria-pressed',soundOn);$('#sound').title=soundOn?'关闭环境音':'开启环境音';toast(soundOn?'环境音已开启':'环境音已关闭')}catch{toast('此浏览器暂不支持环境音。')}}
function applySettings(){document.body.classList.toggle('hide-pinyin',!data.settings.pinyin);document.body.classList.toggle('large-reading',data.settings.large);$('#largeToggle').checked=data.settings.large;$('#challengeMode').value=data.settings.challenge;document.body.classList.toggle('day',data.settings.day);$('#pinyinToggle').checked=data.settings.pinyin;$('#motionToggle').checked=data.settings.reduced;$('#rate').value=String(data.settings.rate);$('#theme').textContent=data.settings.day?'☾':'☀';$('#theme').setAttribute('aria-label',data.settings.day?'切换夜景':'切换日景');$('#theme').title=data.settings.day?'切换夜景':'切换日景';$$('[data-pinyin]').forEach(b=>{b.textContent=data.settings.pinyin?'隐藏拼音':'显示拼音';b.setAttribute('aria-pressed',data.settings.pinyin)});world?.setTheme(data.settings.day?'day':'night');world?.setMotion(!data.settings.reduced);knowledgeUI?.setReduced(data.settings.reduced);refreshVoices();syncScenePause()}
function updateTour(active){$('#tour').textContent=active?'◈ 停止环游':'◈ 环游书院';$('#tour').setAttribute('aria-pressed',active)}
function sceneFallback(message){$('#world').classList.add('disabled-world');document.body.classList.add('no-webgl');$('.interaction-hint').textContent='二维学习模式 · 原文和练习完整可用';$('#sceneStatus').classList.add('hidden');if($('#sceneResume'))$('#sceneResume').hidden=false;updateTour(false)}
function sceneReady(){$('#sceneStatus').classList.add('hidden');$('#world').classList.remove('disabled-world');document.body.classList.remove('no-webgl');if($('#sceneResume'))$('#sceneResume').hidden=true;$('.interaction-hint').textContent=matchMedia('(pointer: coarse)').matches?'单指旋转 · 双指缩放 · 点击地标选课':'拖动环游 · 滚轮缩放 · 点击地标选课';syncScenePause()}
function startScene(){try{world?.dispose();world=null;$('#world').querySelectorAll('canvas').forEach(c=>c.remove());world=createWorld($('#world'),{onSelect:t=>{focusTheme(t);showCurriculum(t)},onReady:sceneReady,onTourChange:updateTour,onContextLost:()=>{world?.setPaused?.(true);sceneFallback();toast('场景暂时中断，学习进度已保留。')},onContextRestored:sceneReady});applySettings()}catch(error){console.warn('书院进入二维学习模式',error);sceneFallback()}}
