$('#settings').onclick=()=>{refreshVoices();showDialog('#settingsDialog')};$('#sound').onclick=toggleSound;$('#theme').onclick=()=>{data.settings.day=!data.settings.day;applySettings();save();toast(data.settings.day?'日景 · 青绿山水':'夜景 · 灯火书院')};$('#pinyinToggle').onchange=e=>{data.settings.pinyin=e.target.checked;applySettings();save()};$('#motionToggle').onchange=e=>{data.settings.reduced=e.target.checked;applySettings();save()};$('#rate').onchange=e=>{data.settings.rate=Number(e.target.value);stopSpeech();save()};
