function mergeRecords(incoming){
 const hadLocalLearning=Boolean(data.completed.length||Object.keys(data.drafts).length||data.visits.length||Object.keys(data.knowledge).length);
 knowledgeUI?.invalidate();const merged=normalizeData(incoming);data.knowledge=mergeKnowledgeProgress(data.knowledge,merged.knowledge);data.reviews=mergeReviews(data.reviews,merged.reviews,CHAPTERS);data.completed=unique([...data.completed,...merged.completed]);data.bookmarks=unique([...data.bookmarks,...merged.bookmarks]);data.visits=unique([...data.visits,...merged.visits]);data.mistakes=unique([...data.mistakes,...merged.mistakes]);
 for(const[id,remote]of Object.entries(merged.drafts)){const local=data.drafts[id];if(!local){data.drafts[id]=remote;continue}const n=Number(id),score=d=>maxStage(d,n,data.completed)*100+d.recallAnswers.filter(Boolean).length*5+d.stage;const chosen=score(remote)>score(local)?remote:local;chosen.readSeen=unique([...local.readSeen,...remote.readSeen]);chosen.orderHelp=local.orderHelp||remote.orderHelp;chosen.quizHelp=local.quizHelp||remote.quizHelp;chosen.quizWrong=unique([...local.quizWrong,...remote.quizWrong]);for(let i=0;i<CHAPTERS[n].verses.length;i++){chosen.recallHelp[i]=Boolean(local.recallHelp[i]||remote.recallHelp[i]);chosen.recallWrong[i]=unique([...(local.recallWrong[i]||[]),...(remote.recallWrong[i]||[])])}data.drafts[id]=chosen}
 syncMistakes();if(!hadLocalLearning){data.last=merged.last;data.knowledgeCursor=merged.knowledgeCursor}if(draft)draft=data.drafts[current]||draft;
}
$('#importButton').onclick=()=>$('#importProgress').click();
$('#importProgress').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1024*1024)throw Error();const p=JSON.parse(await f.text());if(!p||p.version!==1||!Array.isArray(p.completed)||!p.completed.every(validIndex)||!Array.isArray(p.bookmarks)||!p.bookmarks.every(validBookmark))throw Error();if(p.mistakes!==undefined&&(!Array.isArray(p.mistakes)||!p.mistakes.every(validIndex)))throw Error();checkpoint();const before=data.completed.length;mergeRecords(p);save();toast(`记录已合并：新增 ${data.completed.length-before} 课完成记录，本机已有内容已保留。`)}catch{toast('无法导入：请选择本书院导出的有效 JSON 学习记录。')}e.target.value=''};
let clearArmed=false,resetBackup;
