function refreshVoices(){
 const select=$('#voiceChoice');if(!select)return;const voices=listChineseVoices(window.speechSynthesis),selected=data.settings.voiceURI;
 select.innerHTML='<option value="">自动选择普通话声音</option>'+voices.map(v=>`<option value="${esc(v.voiceURI||'')}" ${v.voiceURI===selected?'selected':''}>${esc(v.name)} · ${esc(v.lang)}</option>`).join('');
 if(selected&&!voices.some(v=>v.voiceURI===selected)){const option=document.createElement('option');option.value=selected;option.textContent='原选声音暂不可用 · 自动回退';option.selected=true;select.appendChild(option)}
 $('#voiceStatus').textContent=voices.length?`找到 ${voices.length} 个中文声音。请先试听；多音字和离线可用性仍取决于设备。`:'当前未找到普通话声音。可以继续看原文与拼音，或请陪学者一起读。';
}
